import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, createIssue, inviteAndJoin, uniqueName } from './helpers';

test.describe(`team member: set or change an issue's priority (low, medium, high, urgent) and its assignee`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a teammate updates priority or assignee, all teammates see the updated value within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    const title = uniqueName('issue');
    await createIssue(pageA, { title });

    const cardA = pageA.getByTestId('item-issue').filter({ hasText: title });
    await expect(cardA).toBeVisible({ timeout: 10_000 });
    await cardA.click();
    // Update the assignee to a uniquely-named teammate so the assertion is
    // scoped to a value this test created (the board persists across the run).
    const assignee = uniqueName('assignee');
    await pageA.getByTestId('field-assignee').fill(assignee);
    await pageA.getByTestId('action-set_assignee').click();

    // Teammate B sees the updated assignee on the card within 5s.
    await expect(
      pageB.getByTestId('item-issue').filter({ hasText: title }).filter({ hasText: assignee }),
    ).toBeVisible({ timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });

  test(`priority can only be one of low, medium, high, urgent; other values are rejected`, async ({ page }) => {
    // The create-issue priority control only offers the four valid values — any
    // other value is not selectable, so invalid priorities are rejected at the
    // boundary. Assert the offered set equals exactly the spec's allowed values.
    const ALLOWED_PRIORITIES = ['low', 'medium', 'high', 'urgent'];
    await page.getByTestId('open-new-issue-btn').click();
    const options = await page.getByTestId('field-priority').locator('option').allInnerTexts();
    expect(options.map((o) => o.trim())).toEqual(ALLOWED_PRIORITIES);
  });
});
